import pickle
from phoenix.fgen.tomography import Tomography
from phoenix.fgen.instruction3 import InstructionGroup

# pylint: disable=too-many-arguments


class Routine:
    """Routine class description"""

    def __init__(
        self,
        name: str,
        *,
        itype,
        out_var,
        in_vars,
        instruction_group=None,
    ):
        self._name = name
        if instruction_group is None:
            instruction_group = InstructionGroup([])
        self.instruction_group = instruction_group

        self.in_vars = in_vars
        self.out_var = out_var
        self._itype = itype
        self._ready = False

    def __len__(self):
        return len(self.instruction_group)

    @property
    def itype(self):
        """write-protected access to itype"""
        return self._itype

    @property
    def instructions(self):
        """generator through all instructions.
        Forward the call into the instruction into the top level instruction
        group
        """
        yield from self.instruction_group.instructions

    def checksum(self):
        """a checksum to make sure, that the naming is safe"""
        test_tuple = (
            self._name,
            self.itype,
            len(self.in_vars),
            self.out_var.get_size(),
            *[inp_var.get_size() for inp_var in self.in_vars],
        )
        return test_tuple

    def from_file(self):
        """get from file"""
        filename = f"routine_{self._name}_data.pckl"
        try:
            with open(filename, "rb") as f:
                checksum, instgrp = pickle.load(f)
                if checksum == self.checksum():
                    self.instruction_group = instgrp
                    self._ready = True
                    return self
                else:
                    return False
        except FileNotFoundError:
            return False

    def to_file(self):
        """write to file"""
        filename = f"routine_{self._name}_data.pckl"
        with open(filename, "wb") as f:
            pickle.dump((self.checksum(), self.instruction_group), f)

    # create a tomography object as in
    # tomography = Tomography.new(itype, out_var, in_vars, **kwargs)

    @staticmethod
    def from_function(
        function,  # generating function
        tomography: Tomography,
        name=None,  # name
        parallel=0,  # use multiple cores for generation if > 0
        verbose=False,
        **kwargs,  # catch other arguments if any
    ):
        """generate instructions from function tomography"""

        if name is None:
            name = function.__name__

        # change here: tomography will return an instruction group directly
        instruction_group = tomography.apply(
            function,
            parallel=parallel,
            verbose=verbose,
        )
        return Routine(
            name=name,
            itype=tomography.itype,
            out_var=tomography.out_var,
            in_vars=tomography.in_vars,
            instruction_group=instruction_group,
        )

    @property
    def name(self):
        """make the name read-only, to conserve association to
        instructions and filenames
        """
        return self._name
